import time
import requests
from datetime import datetime

# ==================== CONFIGURATION ====================
# Enter your ngrok public URL generated by Colab:
# (e.g., "https://abc-123.ngrok-free.app")
NGROK_URL = "https://corporate-economic-automatic.ngrok-free.dev"

# Ping interval in seconds (2 minutes)
PING_INTERVAL = 120 
# ========================================================

def ping_server():
    # Clean up base URL
    base_url = NGROK_URL.rstrip('/')
    endpoint = f"{base_url}/api/version"
    
    # Headers required to bypass ngrok free tier browser landing page
    headers = {
        "ngrok-skip-browser-warning": "true",
        "User-Agent": "ColabKeepAlivePinger/1.0"
    }

    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    try:
        response = requests.get(endpoint, headers=headers, timeout=10)
        if response.status_code == 200:
            print(f"[{timestamp}] 🟢 Ping Successful! Ollama Version: {response.json().get('version', 'unknown')}")
        else:
            print(f"[{timestamp}] ⚠️ Received HTTP Status {response.status_code}: {response.text[:100]}")
    except requests.exceptions.RequestException as e:
        print(f"[{timestamp}] ❌ Ping failed. Connection error: {e}")

if __name__ == "__main__":
    print(f"🚀 Starting Keep-Alive Pinger for: {NGROK_URL}")
    print(f"⏱️ Pinging every {PING_INTERVAL} seconds. Press Ctrl+C to stop.\n")
    
    while True:
        ping_server()
        time.sleep(PING_INTERVAL)